mapper.select:
SELECT * FROM ( SELECT ROWNUM rn, TB.* FROM ( SELECT a.BBS_ID, a.BBS_TY_CODE, bt.CODE_NM AS BBS_TY_CODE_NM, a.BBS_NM, a.TMPLAT_ID, a.USE_AT, TO_CHAR(a.FRST_REGIST_PNTTM,'YYYY-MM-DD') AS FRST_REGIST_PNTTM, usr.USER_NM AS FRST_REGISTER_NM FROM COMTNBBSMASTER a LEFT JOIN COMTCCMMNDETAILCODE bt ON bt.CODE_ID='COM101' AND bt.USE_AT='Y' AND bt.CODE=a.BBS_TY_CODE LEFT JOIN COMVNUSERMASTER usr ON usr.ESNTL_ID = a.FRST_REGISTER_ID WHERE 1=1
AND a.CMMNTY_ID = #{cmmntyId}
AND a.BBS_NM LIKE '%'||#{searchWrd}||'%'
AND a.BBS_INTRCN LIKE '%'||#{searchWrd}||'%'
ORDER BY a.FRST_REGIST_PNTTM DESC ) TB ) WHERE rn BETWEEN #{firstIndex}+1 AND #{firstIndex}+#{recordCountPerPage}

SELECT * FROM ( SELECT ROWNUM rn, TB.* FROM ( SELECT a.BLOG_ID, a.BLOG_NM, a.USE_AT, a.REGIST_SE_CODE, dc.CODE_NM AS REGIST_SE_CODE_NM, TO_CHAR(a.FRST_REGIST_PNTTM,'YYYY-MM-DD') AS FRST_REGIST_PNTTM, a.FRST_REGISTER_ID, usr.USER_NM AS FRST_REGISTER_NM, a.BBS_ID, se.AUTHOR_CODE FROM COMTNBLOG a LEFT JOIN COMVNUSERMASTER usr ON usr.ESNTL_ID = a.FRST_REGISTER_ID LEFT JOIN COMTCCMMNDETAILCODE dc ON dc.CODE_ID='COM001' AND dc.CODE = a.REGIST_SE_CODE LEFT JOIN COMTNEMPLYRSCRTYESTBS se ON se.SCRTY_DTRMN_TRGET_ID = a.FRST_REGISTER_ID WHERE dc.CODE_ID='COM001'
AND a.BLOG_NM LIKE '%'||#{searchWrd}||'%'
ORDER BY a.FRST_REGIST_PNTTM DESC ) TB ) WHERE rn BETWEEN #{firstIndex}+1 AND #{firstIndex}+#{recordCountPerPage}

SELECT BLOG_ID, BBS_ID, BLOG_NM, BLOG_INTRCN
  FROM COMTNBLOG
 WHERE BLOG_ID = #{blogId}

SELECT COUNT(FRST_REGISTER_ID)
  FROM COMTNBLOG
 WHERE FRST_REGISTER_ID = #{frstRegisterId}

SELECT FRST_REGISTER_ID
  FROM COMTNBLOG
 WHERE FRST_REGISTER_ID = #{frstRegisterId}
